import{_ as t,o as e,c as o,a2 as n}from"./chunks/framework.z3u3TMv0.js";const u=JSON.parse('{"title":"在 MiniTavern 中配置","description":"","frontmatter":{},"headers":[],"relativePath":"connect-app/minitavern.md","filePath":"connect-app/minitavern.md","lastUpdated":1786085506000}'),l={name:"connect-app/minitavern.md"};function i(s,a,d,r,c,p){return e(),o("div",null,[...a[0]||(a[0]=[n(`<h1 id="在-minitavern-中配置" tabindex="-1">在 MiniTavern 中配置 <a class="header-anchor" href="#在-minitavern-中配置" aria-label="Permalink to &quot;在 MiniTavern 中配置&quot;">​</a></h1><p>本文对应 App 内路径：<strong>设置 → 模型连接</strong>（开发文档称「模型连接 / 配置 AI」）。</p><p>截图可随版本更新替换；以下以文字步骤为准。</p><h2 id="新建连接" tabindex="-1">新建连接 <a class="header-anchor" href="#新建连接" aria-label="Permalink to &quot;新建连接&quot;">​</a></h2><ol><li>打开 MiniTavern → 底部 <strong>设置</strong>。</li><li>进入 <strong>模型连接</strong>。</li><li>点右上角 <strong>新建</strong>。</li><li><strong>模型平台</strong> 选择 <strong>自定义</strong>（OpenAI 兼容 / 自定义 Base URL，以当前版本选项文案为准）。</li><li>填写：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>Ollama 示例</th><th>LM Studio 示例</th></tr></thead><tbody><tr><td>别名</td><td><code>家里Ollama</code></td><td><code>LM Studio</code></td></tr><tr><td>Base URL</td><td><code>http://192.168.1.8:11434/v1</code></td><td><code>http://192.168.1.8:1234/v1</code></td></tr><tr><td>API Key</td><td>可留空或填 <code>ollama</code></td><td>可留空</td></tr><tr><td>默认模型名</td><td><code>llama3.2:3b</code></td><td>与 Local Server 中的模型 id 一致</td></tr></tbody></table><ol start="6"><li>保存。若支持 <strong>测连</strong>，先测连再设为默认。</li></ol><h2 id="设为默认并开聊" tabindex="-1">设为默认并开聊 <a class="header-anchor" href="#设为默认并开聊" aria-label="Permalink to &quot;设为默认并开聊&quot;">​</a></h2><ol><li>在模型连接列表中，将该连接设为 <strong>默认</strong>。</li><li>导入或选择一张角色卡，进入聊天发送一条消息。</li><li>电脑端 Ollama / LM Studio 应出现请求活动；App 内应流式或完整收到回复。</li></ol><h2 id="会话级覆盖-可选" tabindex="-1">会话级覆盖（可选） <a class="header-anchor" href="#会话级覆盖-可选" aria-label="Permalink to &quot;会话级覆盖（可选）&quot;">​</a></h2><p>若某个聊天要临时换本地模型：聊天设置里的模型连接 / 参数可覆盖全局默认（见产品内「聊天设置」）。</p><h2 id="示例配置汇总" tabindex="-1">示例配置汇总 <a class="header-anchor" href="#示例配置汇总" aria-label="Permalink to &quot;示例配置汇总&quot;">​</a></h2><h3 id="ollama" tabindex="-1">Ollama <a class="header-anchor" href="#ollama" aria-label="Permalink to &quot;Ollama&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Base URL:  http://YOUR_PC_IP:11434/v1</span></span>
<span class="line"><span>Model:     llama3.2:3b</span></span>
<span class="line"><span>API Key:   （空或占位）</span></span></code></pre></div><h3 id="lm-studio" tabindex="-1">LM Studio <a class="header-anchor" href="#lm-studio" aria-label="Permalink to &quot;LM Studio&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Base URL:  http://YOUR_PC_IP:1234/v1</span></span>
<span class="line"><span>Model:     （Local Server 显示的模型 id）</span></span>
<span class="line"><span>API Key:   （空或占位）</span></span></code></pre></div><h2 id="注意" tabindex="-1">注意 <a class="header-anchor" href="#注意" aria-label="Permalink to &quot;注意&quot;">​</a></h2><ul><li><strong>禁止</strong> 在手机上填 <code>http://localhost:...</code> 或 <code>http://127.0.0.1:...</code>。</li><li>URL 末尾建议带 <code>/v1</code>，不要填到 <code>/chat/completions</code>。</li><li>电脑休眠、合盖、切网络后 IP 可能变化，连不上时先重新确认 IP。</li></ul><p>连不上时请看 <a href="./../troubleshoot">排错对照表</a>。</p>`,19)])])}const m=t(l,[["render",i]]);export{u as __pageData,m as default};
